def compute(vars):
    old_value = vars["v1"]
    new_value = vars["v2"]
    if old_value == 0:
        return {"value": None, "trace": {"old_value": old_value, "new_value": new_value, "output_meta": {"currency": None, "scale": None, "unit": "percent"}}}
    change = new_value - old_value
    value = change / old_value * 100
    return {
        "value": value,
        "trace": {
            "old_value": old_value,
            "new_value": new_value,
            "change": change,
            "output_meta": {"currency": None, "scale": None, "unit": "percent"}
        }
    }
